@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : float
}

class Car {
  + NumberOfSeats : int
}

class Van {}

class Order {
  + Origin : Location
  + Destination : Location
  + ExecutionDate : date
}

Location "1" *-- "*" Driver
Location "1" *-- "*" Vehicle
Vehicle --|> Truck
Vehicle --|> Car
Vehicle --|> Van

Driver "1" -- "0..1" Order : carries
Driver "0..1" -- "1" Vehicle : drives

@enduml

